import fs from'node:fs';import assert from'node:assert/strict';import{createCommon}from'../create-common.mjs';import{defaultState}from'../src/State.mjs';
const m=createCommon();m.canonical.neckContour=null;m.canonical.neckFairing=null;m.neckSurface=null;const neutral=m.compute(defaultState()).slice(),s=defaultState();s.gnm.rotation[2]=.2;s.gnm.translation[0]=.003;const posed=m.compute(s).slice(),a=m.anny.arrays,J=m.gnm._jointsBind,pivot=[J[0],-J[2]-.016,J[1]+.445],angle=-Math.fround(.2),co=Math.cos(angle),si=Math.sin(angle);let max=0,partial=0,unweightedExact=true;
